CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,display TEXT NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,recovery TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS relations(a TEXT NOT NULL REFERENCES users(id),b TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,PRIMARY KEY(a,b,kind));
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,data TEXT NOT NULL,updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(user_id TEXT NOT NULL,request_id TEXT NOT NULL,response TEXT NOT NULL,created BIGINT NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE IF NOT EXISTS results(room_id TEXT PRIMARY KEY,data TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,sender TEXT NOT NULL REFERENCES users(id),recipient TEXT NOT NULL REFERENCES users(id),room_id TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,target_id TEXT NOT NULL,room_id TEXT NOT NULL,reason TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_owner(id INTEGER PRIMARY KEY,epoch TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE INDEX IF NOT EXISTS invites_recipient ON invites(recipient,expires);
CREATE INDEX IF NOT EXISTS receipts_expiry ON receipts(created);
